#!/usr/bin/env python3
import os
import re
from datetime import datetime
from PIL import Image
import pytesseract
import pandas as pd

def extract_date_from_text(text):
    """Extract date from receipt text and return in YYYY-MM-DD format or None."""
    # Common date patterns in receipts
    date_patterns = [
        r'\b(\d{4})[-/](\d{1,2})[-/](\d{1,2})\b',  # YYYY-MM-DD or YYYY/MM/DD
        r'\b(\d{1,2})[-/](\d{1,2})[-/](\d{4})\b',  # MM-DD-YYYY or MM/DD/YYYY
        r'\b(\d{1,2})[-/](\d{1,2})[-/](\d{2})\b',   # MM-DD-YY or MM/DD/YY
        r'\b(\d{1,2})\.(\d{1,2})\.(\d{2,4})\b',     # DD.MM.YYYY or DD.MM.YY
        r'\b(\d{1,2})\s+(\d{1,2})\s+(\d{2,4})\b',   # DD MM YYYY
    ]

    for pattern in date_patterns:
        matches = re.findall(pattern, text)
        for match in matches:
            try:
                if len(match[0]) == 4:  # Year is first (YYYY-MM-DD)
                    year, month, day = int(match[0]), int(match[1]), int(match[2])
                elif len(match[2]) == 4:  # Year is last (MM-DD-YYYY or DD-MM-YYYY)
                    # Try both interpretations
                    for month_first in [True, False]:
                        if month_first:
                            month, day, year = int(match[0]), int(match[1]), int(match[2])
                        else:
                            day, month, year = int(match[0]), int(match[1]), int(match[2])

                        if year < 100:
                            year += 2000

                        if 1 <= month <= 12 and 1 <= day <= 31:
                            return f"{year:04d}-{month:02d}-{day:02d}"
                else:  # 2-digit year
                    if len(match[2]) == 2:
                        year = int(match[2]) + 2000
                    else:
                        year = int(match[2])

                    # Try both MM-DD and DD-MM
                    for month_first in [True, False]:
                        if month_first:
                            month, day = int(match[0]), int(match[1])
                        else:
                            day, month = int(match[0]), int(match[1])

                        if 1 <= month <= 12 and 1 <= day <= 31:
                            return f"{year:04d}-{month:02d}-{day:02d}"
            except:
                continue

    return None

def extract_total_amount(text):
    """Extract total amount from receipt text."""
    # Keywords to look for (sorted by priority)
    keywords = [
        r'GRAND\s+TOTAL',
        r'TOTAL\s+RM\b',
        r'TOTAL:\s*RM',
        r'TOTAL\s+AMOUNT',
        r'BALANCE\s+DUE',
        r'NETT\s+TOTAL',
        r'NET\s+TOTAL',
        r'AMOUNT\s+DUE',
        r'TOTAL\s+DUE',
        r'AMOUNT',
        r'TOTAL'
    ]

    # Exclusion keywords - skip lines with these
    exclude_keywords = [
        'SUBTOTAL',
        'SUB TOTAL',
        'TAX',
        'GST',
        'SST',
        'DISCOUNT',
        'CHANGE',
        'CASH TENDERED'
    ]

    lines = text.split('\n')

    # First pass: look for lines with priority keywords
    for keyword_pattern in keywords:
        for i, line in enumerate(lines):
            if re.search(keyword_pattern, line, re.IGNORECASE):
                # Check if line contains exclusion keywords
                if any(exclude.lower() in line.lower() for exclude in exclude_keywords):
                    continue

                # Look for amount in this line
                amount_match = re.search(r'(\d{1,3}(?:,\d{3})*(?:\.\d{2})|\d+\.\d{2})', line)
                if amount_match:
                    return amount_match.group(1)

                # Fallback: check next line for amount
                if i + 1 < len(lines):
                    next_line = lines[i + 1]
                    amount_match = re.search(r'(\d{1,3}(?:,\d{3})*(?:\.\d{2})|\d+\.\d{2})', next_line)
                    if amount_match:
                        return amount_match.group(1)

    # Second pass: look for standalone amounts (largest monetary values)
    amounts = []
    for i, line in enumerate(lines):
        if any(exclude.lower() in line.lower() for exclude in exclude_keywords):
            continue

        # Look for amounts in the line
        amount_matches = re.findall(r'(\d{1,3}(?:,\d{3})*(?:\.\d{2})|\d+\.\d{2})', line)
        if amount_matches:
            for amount_str in amount_matches:
                try:
                    # Remove commas and convert to float
                    amount_val = float(amount_str.replace(',', ''))
                    amounts.append((amount_val, line))
                except:
                    continue

    if amounts:
        # Return the largest amount found
        amounts.sort(key=lambda x: x[0], reverse=True)
        return f"{amounts[0][0]:.2f}"

    return None

def process_images(image_dir):
    """Process all images in the directory and extract data."""
    results = []

    # Get all JPG files and sort them
    image_files = sorted([f for f in os.listdir(image_dir) if f.lower().endswith('.jpg')])

    for filename in image_files:
        filepath = os.path.join(image_dir, filename)

        try:
            # Open and process image
            image = Image.open(filepath)

            # Extract text using OCR
            text = pytesseract.image_to_string(image)

            # Extract date and total amount
            date = extract_date_from_text(text)
            total_amount = extract_total_amount(text)

            # Format total_amount to have exactly 2 decimal places
            if total_amount:
                try:
                    # Handle comma separators
                    if ',' in total_amount:
                        total_amount = total_amount.replace(',', '')
                    total_amount = f"{float(total_amount):.2f}"
                except:
                    total_amount = None

            results.append({
                'filename': filename,
                'date': date,
                'total_amount': total_amount
            })

            print(f"Processed {filename}: date={date}, total={total_amount}")

        except Exception as e:
            print(f"Error processing {filename}: {e}")
            results.append({
                'filename': filename,
                'date': None,
                'total_amount': None
            })

    return results

def main():
    image_dir = '/app/workspace/dataset/img'
    output_file = '/app/workspace/stat_ocr.xlsx'

    print("Starting OCR extraction...")
    results = process_images(image_dir)

    # Create DataFrame and save to Excel
    df = pd.DataFrame(results)

    # Write to Excel with only 'results' sheet
    with pd.ExcelWriter(output_file, engine='openpyxl') as writer:
        df.to_excel(writer, sheet_name='results', index=False)

    print(f"\nResults saved to {output_file}")
    print(f"Total receipts processed: {len(results)}")

if __name__ == '__main__':
    main()

